import glob, os, sys, shutil, subprocess
URLS_SRC = '"""URL 파싱 유틸리티.\n\n학습·평가·서버 추론이 모두 이 모듈을 쓰므로 전처리 기준이 하나로 유지된다(제안서 2.2절).\nURL은 문자열로만 다루며 어떤 네트워크 접속도 하지 않는다.\n"""\n\nimport ipaddress\nimport re\nfrom functools import lru_cache\nfrom urllib.parse import urlsplit\n\nSUPPORTED_SCHEMES = ("http", "https")\nMAX_URL_CHARS = 2048\n\n_SCHEME_RE = re.compile(r"^([A-Za-z][A-Za-z0-9+.\\-]*):(.*)$", re.DOTALL)\n_PORT_RE = re.compile(r"^\\d+(?:[/?#]|$)")\n_HTTP_PREFIX_RE = re.compile(r"^https?://", re.IGNORECASE)\n_WWW_PREFIX_RE = re.compile(r"^www\\.", re.IGNORECASE)\n\n# 유명 단축 URL 서비스 (최종 목적지는 확인하지 않는다 — 제안서 4.3절)\nKNOWN_SHORTENERS = frozenset({\n    "bit.ly", "bitly.com", "tinyurl.com", "t.co", "goo.gl", "is.gd", "ow.ly", "buff.ly",\n    "rebrand.ly", "cutt.ly", "shorturl.at", "tiny.cc", "rb.gy", "bit.do", "lnkd.in",\n    "me2.do", "vo.la", "han.gl", "url.kr", "s.id", "v.gd", "t.ly", "shorturl.asia",\n})\n\n# tldextract가 없을 때 쓰는 2단계 공용 접미사 (대표적인 것만)\n_FALLBACK_SECOND_LEVEL = frozenset({\n    "co.kr", "or.kr", "go.kr", "ac.kr", "ne.kr", "re.kr", "pe.kr", "ms.kr", "hs.kr", "es.kr", "sc.kr",\n    "co.uk", "org.uk", "ac.uk", "gov.uk", "me.uk", "ltd.uk", "plc.uk",\n    "co.jp", "ne.jp", "or.jp", "ac.jp", "go.jp",\n    "com.au", "net.au", "org.au", "edu.au", "gov.au",\n    "com.br", "com.cn", "net.cn", "org.cn", "gov.cn", "com.tw", "com.hk", "com.sg", "com.my",\n    "co.in", "net.in", "org.in", "gov.in", "co.id", "co.za", "co.nz", "com.mx", "com.ar",\n    "com.tr", "com.vn", "com.ph", "com.pk", "com.ng", "com.eg", "com.sa", "com.ua", "co.il",\n})\n\n\n@lru_cache(maxsize=1)\ndef _tld_extractor():\n    """오프라인(내장 Public Suffix List 스냅샷) tldextract. 없으면 None."""\n    try:\n        import tldextract\n    except ImportError:\n        return None\n    return tldextract.TLDExtract(suffix_list_urls=(), cache_dir=None)\n\n\ndef using_tldextract():\n    return _tld_extractor() is not None\n\n\ndef detect_scheme(url):\n    """URL의 scheme을 판별한다.\n\n    반환: (scheme 또는 None, \'hierarchical\'|\'opaque\'|\'none\')\n    - \'http://a.com\' -> (\'http\', \'hierarchical\')\n    - \'javascript:alert(1)\' -> (\'javascript\', \'opaque\')\n    - \'a.com:8080/x\', \'a.com/x\' -> (None, \'none\')\n    """\n    m = _SCHEME_RE.match(url)\n    if not m:\n        return None, "none"\n    scheme, rest = m.group(1).lower(), m.group(2)\n    if rest.startswith("//"):\n        return scheme, "hierarchical"\n    # 점이 들어간 호스트(\'a.com:8080\')나 \'localhost:포트\'는 scheme이 아니다.\n    # \'tel:0101234\'처럼 점 없는 단어 뒤 숫자는 scheme으로 본다.\n    if "." in scheme or (scheme == "localhost" and _PORT_RE.match(rest)):\n        return None, "none"\n    return scheme, "opaque"\n\n\ndef split_url(url):\n    """URL을 urlsplit 결과로 나눈다. scheme이 없으면 http://를 임시로 붙인다(저장 URL은 바꾸지 않음)."""\n    scheme, kind = detect_scheme(url)\n    target = url if kind == "hierarchical" else "http://" + url\n    return urlsplit(target)\n\n\ndef parse_host(url):\n    """호스트를 소문자로 돌려준다. 추출할 수 없으면 None. 포트와 사용자정보는 제외된다."""\n    if not isinstance(url, str):\n        return None\n    s = url.strip()\n    if not s:\n        return None\n    try:\n        host = split_url(s).hostname\n    except ValueError:\n        return None\n    if not host:\n        return None\n    host = host.strip(".")\n    if not host:\n        return None\n    if is_ip(host):\n        return host\n    if "." not in host and host != "localhost":\n        return None\n    if not re.fullmatch(r"[a-z0-9\\-._~%!$&\'()*+,;=¡-\uffff]+", host):\n        return None\n    return host\n\n\ndef is_ip(host):\n    try:\n        ipaddress.ip_address(host.strip("[]"))\n        return True\n    except ValueError:\n        return False\n\n\ndef registered_domain(host):\n    """등록 도메인(그룹 키). IP면 IP 자체. \'login.secure.example.co.kr\' -> \'example.co.kr\'."""\n    if host is None:\n        return None\n    if is_ip(host):\n        return host\n    ext = _tld_extractor()\n    if ext is not None:\n        r = ext(host)\n        if r.domain and r.suffix:\n            return f"{r.domain}.{r.suffix}"\n        return host\n    labels = host.split(".")\n    if len(labels) >= 3 and ".".join(labels[-2:]) in _FALLBACK_SECOND_LEVEL:\n        return ".".join(labels[-3:])\n    return ".".join(labels[-2:]) if len(labels) >= 2 else host\n\n\ndef check_url(url):\n    """추론 전 입력 검사. 반환: (status, host)\n\n    status: \'ok\' | \'invalid_url\' | \'unsupported_scheme\'\n    """\n    if not isinstance(url, str) or not url.strip():\n        return "invalid_url", None\n    s = url.strip()\n    scheme, kind = detect_scheme(s)\n    if kind == "opaque" or (kind == "hierarchical" and scheme not in SUPPORTED_SCHEMES):\n        return "unsupported_scheme", None\n    host = parse_host(s)\n    if host is None:\n        return "invalid_url", None\n    return "ok", host\n\n\n_HOME_SLASH_RE = re.compile(r"^([^/?#]+)/$")\n\n\ndef normalize(url, mode):\n    """모델 입력 정규화.\n\n    - raw   : 공백 제거만\n    - strip : 앞쪽 http(s)://와 www. 제거\n    - strip2: strip + 경로가 \'/\' 하나뿐인 홈페이지 형태의 끝 \'/\' 제거 (\'a.com/\' → \'a.com\')  [개정 5]\n    """\n    s = url.strip()\n    if mode == "raw":\n        return s\n    if mode in ("strip", "strip2"):\n        s = _HTTP_PREFIX_RE.sub("", s)\n        s = _WWW_PREFIX_RE.sub("", s)\n        if mode == "strip2":\n            s = _HOME_SLASH_RE.sub(r"\\1", s)\n        return s\n    raise ValueError(f"알 수 없는 정규화 방식: {mode}")\n\n\nSCHEME_VARIANTS = ("noscheme", "https")\n\n\ndef scheme_variant(url, kind):\n    """scheme 편향 점검용 변형.\n\n    \'noscheme\': 앞쪽 http(s)://를 뗀다 / \'https\': scheme이 없으면 https://를 붙인다(QR URL과 비슷한 형태).\n    """\n    s = url.strip()\n    if kind == "noscheme":\n        return _HTTP_PREFIX_RE.sub("", s)\n    if kind == "https":\n        return s if detect_scheme(s)[1] == "hierarchical" else "https://" + s\n    raise ValueError(f"알 수 없는 변형: {kind}")\n\n\ndef loose_key(url):\n    """라벨 충돌 검사용 키: scheme·www. 제거, 호스트 부분만 소문자. 경로·쿼리는 그대로."""\n    s = normalize(url, "strip")\n    m = re.search(r"[/?#]", s)\n    if m:\n        return s[: m.start()].lower() + s[m.start():]\n    return s.lower()\n\n\ndef scheme_kind(url):\n    """scheme 점검용 분류: \'https\' | \'http\' | \'none\' | \'other\'."""\n    scheme, kind = detect_scheme(url.strip())\n    if kind == "none":\n        return "none"\n    return scheme if scheme in SUPPORTED_SCHEMES else "other"\n\n\ndef signals(url, host=None):\n    """URL 규칙 점검 결과(보조 정보, 제안서 3.3절). AI 판단 이유가 아니다."""\n    s = url.strip()\n    host = host if host is not None else parse_host(s)\n    ip = host is not None and is_ip(host)\n    depth = 0\n    if host and not ip:\n        reg = registered_domain(host)\n        depth = max(0, host.count(".") - reg.count("."))\n    try:\n        netloc = split_url(s).netloc\n    except ValueError:\n        netloc = ""\n    return {\n        "is_ip_host": bool(ip),\n        "subdomain_depth": int(depth),\n        "has_at_symbol": "@" in netloc,\n        "has_punycode": bool(host) and "xn--" in host,\n        "url_length": len(s),\n        "is_known_shortener": bool(host) and (registered_domain(host) in KNOWN_SHORTENERS or host in KNOWN_SHORTENERS),\n    }\n'
AUGMENT_SRC = '"""v3 (설계 개정 4): 정상 홈페이지 형태 보강과 원인 확인.\n\nv2에서 PhiUSIIL 정상 URL 99%, Tranco 홈페이지 24%를 악성으로 판정했다.\n가설: Malicious URLs의 benign은 경로가 긴 URL 위주라 \'도메인만 있는 URL\'을 정상으로 본 적이 거의 없다.\n\n- path_profile: 클래스별 홈페이지 형태(경로·쿼리 없음) 비율로 가설을 확인한다.\n- homepage_rows: 각 세트의 정상 URL 호스트로 \'https://호스트/\'를 만들어 정상으로 추가한다.\n  악성 URL(어느 클래스든, 어느 세트든)에 나온 호스트는 제외한다(변조된 정상 사이트 등 라벨이 모호).\n  호스트의 등록 도메인이 원래 행과 같으므로 세트 배정이 그대로 유지되어 누수가 없다.\n  새 출처를 쓰지 않으므로 출처-클래스 혼입도 없다.\n"""\n\nimport os\nimport time\n\nimport numpy as np\nimport pandas as pd\n\nfrom . import urls as U\nfrom .labels import LABELS, to_ids\n\n\ndef is_homepage(url):\n    """경로가 비었거나 \'/\'뿐이고 쿼리·프래그먼트가 없는 URL."""\n    try:\n        sp = U.split_url(url.strip())\n    except ValueError:\n        return False\n    return sp.path in ("", "/") and not sp.query and not sp.fragment\n\n\ndef path_profile(df):\n    """클래스별 홈페이지 형태 비율(%), 쿼리 포함 비율(%), 길이 중앙값."""\n    home = df["url"].map(is_homepage)\n    query = df["url"].map(lambda u: "?" in u)\n    length = df["url"].str.len()\n    out = pd.DataFrame({\n        "rows": df.groupby("label").size(),\n        "homepage_pct": home.groupby(df["label"]).mean() * 100,\n        "query_pct": query.groupby(df["label"]).mean() * 100,\n        "median_len": length.groupby(df["label"]).median(),\n    })\n    return out.round(2)\n\n\ndef homepage_rows(d):\n    """분리된 Malicious URLs(d, split 컬럼 포함)에서 정상 홈페이지 보강 행을 만든다."""\n    host = d["url"].map(U.parse_host)\n    mal_hosts = set(host[d["label"] != "benign"])\n    existing = set(d["url"].map(U.loose_key))\n    rows = []\n    benign = d[d["label"] == "benign"].assign(_host=host[d["label"] == "benign"])\n    for (h, split, g), _ in benign.groupby(["_host", "split", "group_key"]):\n        if h in mal_hosts:\n            continue\n        url = f"https://{h}/"\n        if U.loose_key(url) in existing:\n            continue\n        rows.append((url, "benign", "aug_homepage", split, g))\n    out = pd.DataFrame(rows, columns=["url", "label", "source", "split", "group_key"])\n    return out.drop_duplicates("url").reset_index(drop=True)\n\n\ndef run_v3(cfg, P, v2_reports_dir=None, log=print, zip_path="/kaggle/working/qsing_artifacts",\n           extra_rows=None, post_eval=None):\n    """P1 → P10 원인 확인 → P2 → 보강 → 임베딩 → 학습(선택 기준에 홈페이지 val 추가) → P6 → P5(+홈페이지) → P7.\n\n    P: qsing_model.pipeline 모듈. cfg.normalizations는 (\'strip\',) 권장(v2에서 raw의 scheme 지름길 확인).\n    extra_rows(cfg, P, d, aug, log) -> 보강 행 DataFrame (개정 6): split이 \'train\'이면 학습에, 그 밖의 값이면 평가 전용.\n    post_eval(cfg, P, aug, sel, thr, mm, log) -> 내보내기 전에 metrics에 추가 평가를 넣는다.\n    """\n    from .head import NumpyHead\n    from .metrics import four_class_metrics, benign_fpr\n    from .risk import risk_score\n\n    P.p1_prepare(cfg)\n    P._hr("P10 원인 확인: 클래스별 홈페이지 형태 비율")\n    mal_c = P.load_df(cfg, "mal_clean")\n    prof = path_profile(mal_c)\n    log(prof.to_string())\n    rep10 = {"malicious_urls": prof.to_dict(orient="index")}\n    if P.has_df(cfg, "phi_clean"):\n        pp = path_profile(P.load_df(cfg, "phi_clean"))\n        rep10["phiusiil"] = pp.to_dict(orient="index")\n        log("PhiUSIIL:\\n" + pp.to_string())\n    P._jdump(rep10, cfg.path("reports", "p10_path_profile.json"))\n\n    P.p2_split(cfg)\n    d = P.load_df(cfg, "mal_split")\n    P._hr("P11 정상 홈페이지 보강 행 만들기")\n    aug = homepage_rows(d)\n    if extra_rows is not None:\n        aug = pd.concat([aug, extra_rows(cfg, P, d, aug, log)], ignore_index=True)\n    P.save_df(aug, cfg, "home_aug")\n    rep11 = {s: int((aug["split"] == s).sum()) for s in ("train", "val", "test")}\n    rep11["excluded_rule"] = "악성 URL에 나온 호스트 제외, 이미 있는 URL 제외"\n    rep11["train_by_source"] = {k: int(v) for k, v in aug.loc[aug["split"] == "train", "source"].value_counts().items()}\n    log(f"보강 행: {rep11}")\n    P._jdump(rep11, cfg.path("reports", "p11_augment.json"))\n\n    if v2_reports_dir and os.path.exists(os.path.join(v2_reports_dir, "p3_baseline_metrics.json")):\n        import shutil\n        shutil.copy(os.path.join(v2_reports_dir, "p3_baseline_metrics.json"), cfg.path("reports", "p3_baseline_metrics.json"))\n        log("기준선(P3)은 v2 결과를 그대로 사용 (같은 test 세트)")\n    else:\n        P.p3_baseline(cfg)\n\n    P.p4_embed(cfg)\n    from .embed import Embedder\n    emb = Embedder(cfg.repo, revision=cfg.revision)\n    for norm in cfg.normalizations:\n        X, _ = emb.encode([U.normalize(u, norm) for u in aug["url"]], batch_size=cfg.embed_batch, progress=True)\n        np.save(cfg.path("emb", f"{norm}_home.npy"), X)\n    del emb\n    P._free_gpu()\n\n    def xy(norm, split, with_aug):\n        X, y = P._load_xy(cfg, norm, split)\n        if not with_aug:\n            return X, y\n        sel = (aug["split"] == split).values\n        Xa = np.load(cfg.path("emb", f"{norm}_home.npy"))[sel]\n        return np.concatenate([X, Xa]), np.concatenate([y, np.array(to_ids(aug.loc[sel, "label"]), dtype=int)])\n\n    P._hr("P11 헤드 학습 (train + 홈페이지 보강), 선택 = val Macro F1 최저값(원본·scheme 변형·홈페이지 포함)")\n    from .train import train_head\n    runs = []\n\n    def robust(info):\n        worst, f1s = P._robust_val_f1(cfg, info)\n        head = NumpyHead.load(info["head_file"], info["spec"])\n        Xh, yh = xy(info["normalization"], "val", True)\n        f1s["home"] = four_class_metrics(yh, head.probs(Xh.astype(np.float32)).argmax(1))["macro_f1"]\n        return min(worst, f1s["home"]), f1s\n\n    for norm in cfg.normalizations:\n        Xtr, ytr = xy(norm, "train", True)\n        Xva, yva = xy(norm, "val", False)\n        for kind in cfg.head_kinds:\n            info = P._train_one(cfg, train_head, norm, kind, cfg.seed, Xtr, ytr, Xva, yva)\n            info["val_macro_f1_worst"], info["val_macro_f1_variants"] = robust(info)\n            runs.append(info)\n    table = pd.DataFrame([{"normalization": r["normalization"], "kind": r["kind"], "seed": r["seed"],\n                           "val_f1_original": r["val_macro_f1_variants"]["original"],\n                           "val_f1_home": r["val_macro_f1_variants"]["home"],\n                           "val_f1_worst": r["val_macro_f1_worst"], "best_epoch": r["best_epoch"],\n                           "seconds": r["seconds"]} for r in runs])\n    log("\\n" + table.to_string(index=False))\n    best = max(runs, key=lambda r: (round(r["val_macro_f1_worst"], 6), -cfg.head_kinds.index(r["kind"])))\n    seed_runs = [best]\n    Xtr, ytr = xy(best["normalization"], "train", True)\n    Xva, yva = xy(best["normalization"], "val", False)\n    for s in cfg.extra_seeds:\n        info = P._train_one(cfg, train_head, best["normalization"], best["kind"], s, Xtr, ytr, Xva, yva)\n        info["val_macro_f1_worst"], info["val_macro_f1_variants"] = robust(info)\n        seed_runs.append(info)\n    f1s = [r["best_val_macro_f1"] for r in seed_runs]\n    sel = {\n        "normalization": best["normalization"], "kind": best["kind"], "seed": cfg.seed,\n        "head_file": best["head_file"], "spec": best["spec"],\n        "val_macro_f1": best["best_val_macro_f1"], "val_macro_f1_worst": best["val_macro_f1_worst"],\n        "val_macro_f1_variants": best["val_macro_f1_variants"],\n        "selection_metric": "val Macro F1 최저값 (원본, scheme 제거, https 추가, 정상 홈페이지 보강 val)",\n        "training_data": "Malicious URLs train + " + ", ".join(f"{k} {v}행" for k, v in rep11["train_by_source"].items()),\n        "seeds": [r["seed"] for r in seed_runs], "seed_val_macro_f1": f1s,\n        "seed_val_macro_f1_worst": [r["val_macro_f1_worst"] for r in seed_runs],\n        "seed_mean": float(np.mean(f1s)), "seed_std": float(np.std(f1s, ddof=1)) if len(f1s) > 1 else 0.0,\n        "all_runs": [{**row, "val_f1_noscheme": None, "val_f1_https": None} for row in table.to_dict(orient="records")],\n        "selected_on": "val",\n    }\n    P._jdump(sel, cfg.path("reports", "p4_selection.json"))\n    log(f"선택: {sel[\'normalization\']} + {sel[\'kind\']}, val 최저 {sel[\'val_macro_f1_worst\']:.4f}, "\n        f"시드 평균 {sel[\'seed_mean\']:.4f} ± {sel[\'seed_std\']:.4f}")\n\n    thr = P.p6_thresholds(cfg)\n    m = P.p5_evaluate(cfg)\n\n    P._hr("P12 홈페이지 형태 평가 (test 세트 정상 호스트의 홈페이지)")\n    head = NumpyHead.load(sel["head_file"], sel["spec"])\n    norm = sel["normalization"]\n    sel_te = (aug["split"] == "test").values\n    Xa = np.load(cfg.path("emb", f"{norm}_home.npy"))[sel_te].astype(np.float32)\n    pa = head.probs(Xa)\n    ya = np.array(to_ids(aug.loc[sel_te, "label"]))\n    home = {"n": int(sel_te.sum()),\n            "benign_fpr": {"argmax": benign_fpr(ya, pa.argmax(1) != 0),\n                           "threshold": benign_fpr(ya, risk_score(pa) >= thr["t_low"])}}\n    Xt, yt = xy(norm, "test", True)\n    pt = head.probs(Xt.astype(np.float32))\n    mt = four_class_metrics(yt, pt.argmax(1), flagged_by_threshold=risk_score(pt) >= thr["t_low"])\n    home["test_plus_home"] = {k: mt[k] for k in ("n", "accuracy", "macro_f1", "benign_fpr", "malicious_fnr")}\n    log(f"홈페이지 형태 test (n={home[\'n\']}): 정상 오탐률 {home[\'benign_fpr\']}")\n    log(f"test + 홈페이지: {home[\'test_plus_home\']}")\n    mm = P._jload(cfg.path("reports", "metrics.json"))\n    mm["test_homepage"] = home\n    mm["path_profile"] = rep10\n    mm["augment"] = rep11\n    if post_eval is not None:\n        mm = post_eval(cfg, P, aug, sel, thr, mm, log)\n    P._jdump(mm, cfg.path("reports", "metrics.json"))\n\n    P.p7_export(cfg, zip_path=zip_path)\n    return P.run_summary_md(cfg)\n'
CCAUG_SRC = '"""v5 (설계 개정 6): 다른 출처 정상 URL 보강 (Common Crawl).\n\nMalicious URLs의 정상 URL은 ISCX-URL-2016에서 왔고, 그 데이터는 도메인만 있는 URL을 제거하고 만들었다.\n같은 데이터 안에서 형식만 바꾸는 방법(v3 홈페이지 보강, v4 strip2)으로는 다른 출처 정상 URL 오탐을 다 줄이지 못했다.\n\n- 추가 데이터: HuggingFace JPxxx/url-benchmark-dataset (정상 = Common Crawl, 악성 = PhishTank·URLhaus 등, Apache-2.0)\n- train 세트에만 정상 URL을 추가한다. val·test·외부 평가 세트는 v4와 같다.\n- 누수 방지: val·test 도메인, 외부 평가 도메인, 악성에 나온 호스트, 이미 있는 URL을 뺀다. 도메인당 최대 per_domain건.\n- holdout: 학습에 쓰지 않은 도메인의 정상·악성 URL로 \'처음 보는 출처\' 평가를 한다(악성 종류 라벨이 없어 2종 지표만).\n"""\n\nimport numpy as np\nimport pandas as pd\n\nfrom . import data as D\nfrom . import urls as U\nfrom .labels import BENIGN_ID, to_ids\n\nJP_REPO = "JPxxx/url-benchmark-dataset"\nJP_FILE = "data/train-00000-of-00001.parquet"\n_LABEL_MAP = {"benign": "benign", "0": "benign", "malicious": "malicious", "1": "malicious"}\n\n\ndef fetch_jp():\n    """Kaggle 입력에 parquet이 있으면 그것을, 없으면 HuggingFace에서 내려받는다."""\n    hits = D.find_files([JP_FILE.split("/")[-1]], roots=("/kaggle/input",))\n    if hits:\n        return hits[0]\n    from huggingface_hub import hf_hub_download\n    return hf_hub_download(JP_REPO, JP_FILE, repo_type="dataset")\n\n\ndef load_jp(path):\n    """url, label(benign|malicious) 두 컬럼으로 읽는다. 라벨은 문자열이든 0/1이든 받는다."""\n    if str(path).lower().endswith(".csv"):\n        raw = pd.read_csv(path, dtype=str, keep_default_na=False)\n    else:\n        raw = pd.read_parquet(path, columns=["url", "label"])\n    lab = raw["label"].astype(str).str.strip().str.lower().map(_LABEL_MAP)\n    if lab.isna().any():\n        raise ValueError(f"알 수 없는 label 값: {raw.loc[lab.isna(), \'label\'].unique()[:5]}")\n    share = float((lab == "benign").mean())\n    if not 0.5 < share < 0.99:\n        raise ValueError(f"benign 비율 {share:.3f}가 데이터 카드(약 0.9)와 다릅니다. 라벨 해석을 확인하세요.")\n    return pd.DataFrame({"url": raw["url"].astype(str), "label": lab})\n\n\ndef cc_rows(d, aug, jp, eval_groups, collected_at, seed=42, n_train=200_000, n_hold=20_000, per_domain=3,\n            pool_benign=1_000_000, pool_malicious=150_000):\n    """보강 행을 만든다. 반환: (DataFrame[url,label,source,split,group_key], 리포트).\n\n    d: 분리된 Malicious URLs(split, group_key 포함) / aug: 이미 만든 보강 행 / jp: load_jp 결과\n    eval_groups: 외부 평가 세트(PhiUSIIL·OpenPhish·Tranco)의 등록 도메인 집합\n    """\n    rep = {"jp_rows": int(len(jp)), "jp_label_counts": {k: int(v) for k, v in jp["label"].value_counts().items()}}\n    ben, mal = jp[jp["label"] == "benign"], jp[jp["label"] == "malicious"]\n    if len(ben) > pool_benign:\n        ben = ben.sample(n=pool_benign, random_state=seed)\n    if len(mal) > pool_malicious:\n        mal = mal.sample(n=pool_malicious, random_state=seed)\n    # 악성은 종류를 모르므로 임시로 phishing 라벨을 붙인다(2종 평가에만 사용).\n    frame = pd.concat([D._frame(ben["url"], ["benign"] * len(ben), "cc_benign", collected_at),\n                       D._frame(mal["url"], ["phishing"] * len(mal), "jp_malicious", collected_at)], ignore_index=True)\n    c, rep["clean"] = D.clean(frame)\n    c["host"] = c["url"].map(U.parse_host)\n    c["_lk"] = c["url"].map(U.loose_key)\n\n    mal_groups_all = set(d["group_key"])\n    valtest_groups = set(d.loc[d["split"] != "train", "group_key"])\n    eval_groups = set(eval_groups)\n    jp_mal = c[c["label"] != "benign"]\n    mal_hosts = set(d.loc[d["label"] != "benign", "url"].map(U.parse_host)) | set(jp_mal["host"])\n    existing = set(d["url"].map(U.loose_key)) | set(aug["url"].map(U.loose_key))\n\n    b = c[c["label"] == "benign"]\n    steps = {"benign_after_clean": int(len(b))}\n    b = b[~b["group_key"].isin(valtest_groups)]\n    steps["after_drop_valtest_domains"] = int(len(b))\n    b = b[~b["group_key"].isin(eval_groups)]\n    steps["after_drop_external_eval_domains"] = int(len(b))\n    b = b[~b["host"].isin(mal_hosts)]\n    steps["after_drop_malicious_hosts"] = int(len(b))\n    b = b[~b["_lk"].isin(existing)]\n    steps["after_drop_existing_urls"] = int(len(b))\n    b = b.sample(frac=1.0, random_state=seed)\n    b = b.groupby("group_key", sort=False).head(per_domain)\n    steps["after_per_domain_cap"] = int(len(b))\n    steps["domains_after_cap"] = int(b["group_key"].nunique())\n\n    # holdout 정상: Malicious URLs에도 JP 악성에도 없는 도메인을 통째로 떼어 둔다.\n    new = b[~b["group_key"].isin(mal_groups_all | set(jp_mal["group_key"]))]\n    sizes = new.groupby("group_key", sort=False).size()\n    k = int(np.searchsorted(sizes.cumsum().values, n_hold)) + 1\n    k = max(1, min(k, len(sizes) // 5)) if len(sizes) else 0\n    hold_groups = set(sizes.index[:k])\n    hold_b = new[new["group_key"].isin(hold_groups)]\n    tr = b[~b["group_key"].isin(hold_groups)]\n    if len(tr) > n_train:\n        tr = tr.sample(n=n_train, random_state=seed)\n\n    # holdout 악성: 학습 데이터·외부 평가·train 보강 어디에도 없는 도메인.\n    m = jp_mal[~jp_mal["group_key"].isin(mal_groups_all | eval_groups | set(tr["group_key"]) | hold_groups)]\n    steps["malicious_after_clean"] = int(len(jp_mal))\n    steps["malicious_unseen_domains"] = int(len(m))\n    m = m.sample(frac=1.0, random_state=seed).groupby("group_key", sort=False).head(per_domain)\n    if len(m) > n_hold:\n        m = m.sample(n=n_hold, random_state=seed)\n\n    def pack(df, label, source, split):\n        return pd.DataFrame({"url": df["url"].values, "label": label, "source": source, "split": split,\n                             "group_key": df["group_key"].values})\n\n    out = pd.concat([pack(tr, "benign", "cc_benign", "train"),\n                     pack(hold_b, "benign", "cc_benign_holdout", "holdout"),\n                     pack(m, "phishing", "jp_malicious_holdout", "holdout")], ignore_index=True)\n\n    tr_groups, hold_all = set(tr["group_key"]), hold_groups | set(m["group_key"])\n    assert not tr_groups & valtest_groups, "train 보강 도메인이 val·test와 겹침"\n    assert not tr_groups & eval_groups, "train 보강 도메인이 외부 평가와 겹침"\n    assert not hold_all & (mal_groups_all | tr_groups), "holdout 도메인이 학습 데이터와 겹침"\n\n    from .augment import is_homepage\n    rep["steps"] = steps\n    rep["train"] = {"rows": int(len(tr)), "domains": int(tr["group_key"].nunique()),\n                    "homepage_pct": round(100 * float(tr["url"].map(is_homepage).mean()), 2) if len(tr) else None,\n                    "median_len": float(tr["url"].str.len().median()) if len(tr) else None,\n                    "https_pct": round(100 * float(tr["url"].str.lower().str.startswith("https://").mean()), 2) if len(tr) else None}\n    rep["holdout"] = {"benign_rows": int(len(hold_b)), "benign_domains": int(len(hold_groups)),\n                      "malicious_rows": int(len(m)), "malicious_domains": int(m["group_key"].nunique()),\n                      "benign_homepage_pct": round(100 * float(hold_b["url"].map(is_homepage).mean()), 2) if len(hold_b) else None,\n                      "malicious_homepage_pct": round(100 * float(m["url"].map(is_homepage).mean()), 2) if len(m) else None}\n    rep["rules"] = ["val·test 도메인 제외", "외부 평가(PhiUSIIL·OpenPhish·Tranco) 도메인 제외", "악성에 나온 호스트 제외",\n                    "이미 있는 URL 제외", f"도메인당 최대 {per_domain}건", f"seed {seed}"]\n    return out, rep\n\n\ndef run_v5(cfg, P, v2_reports_dir=None, jp_path=None, log=print, zip_path="/kaggle/working/qsing_artifacts", **kw):\n    """v4 흐름(run_v3, strip2) + Common Crawl 정상 보강(train) + holdout 평가 + 보강 없는 헤드와 비교."""\n    from . import augment as A\n    from .head import NumpyHead\n    from .metrics import binary_metrics, four_class_metrics\n    from .risk import risk_score\n\n    def extra(cfg, P, d, aug, log):\n        P._hr("P14 다른 출처 정상 URL 보강 (Common Crawl, JPxxx/url-benchmark-dataset)")\n        jp = load_jp(jp_path or fetch_jp())\n        eval_groups = set()\n        for name in ("phi_clean", "external"):\n            if P.has_df(cfg, name):\n                eval_groups |= set(P.load_df(cfg, name)["group_key"])\n        rows, rep = cc_rows(d, aug, jp, eval_groups, cfg.collected_at, seed=cfg.seed, **kw)\n        P._jdump(rep, cfg.path("reports", "p14_cc_augment.json"))\n        log(f"JPxxx: {rep[\'jp_label_counts\']}")\n        log(f"필터 단계: {rep[\'steps\']}")\n        log(f"train 보강: {rep[\'train\']}")\n        log(f"holdout: {rep[\'holdout\']}")\n        return rows\n\n    def post(cfg, P, aug, sel, thr, mm, log):\n        P._hr("P15 처음 보는 출처 평가 (JPxxx holdout: 학습에 없는 도메인의 정상·악성)")\n        from .train import train_head\n        norm = sel["normalization"]\n        Xa = np.load(cfg.path("emb", f"{norm}_home.npy"))\n        hold = (aug["split"] == "holdout").values\n        Xh, yh = Xa[hold].astype(np.float32), np.array(to_ids(aug.loc[hold, "label"]))\n\n        def evaluate(head, t_low=None):\n            p = head.probs(Xh)\n            rr = risk_score(p)\n            r = binary_metrics(yh, rr, p.argmax(1) != BENIGN_ID, rr >= t_low if t_low is not None else None)\n            Xt, yt = P._load_xy(cfg, norm, "test")\n            t = four_class_metrics(yt, head.probs(Xt.astype(np.float32)).argmax(1))\n            r["test_check"] = {"macro_f1": t["macro_f1"], "benign_fpr": t["benign_fpr"]["argmax"],\n                               "malicious_fnr": t["malicious_fnr"]["argmax"]}\n            return r\n\n        res = {"with_cc(v5)": evaluate(NumpyHead.load(sel["head_file"], sel["spec"]), thr["t_low"])}\n        # 비교 기준: 같은 시드·같은 설정에서 Common Crawl 보강만 뺀 헤드 (= v4 재현)\n        Xm, ym = P._load_xy(cfg, norm, "train")\n        home = ((aug["split"] == "train") & (aug["source"] == "aug_homepage")).values\n        Xtr = np.concatenate([Xm, Xa[home]])\n        ytr = np.concatenate([ym, np.array(to_ids(aug.loc[home, "label"]), dtype=int)])\n        Xva, yva = P._load_xy(cfg, norm, "val")\n        info = P._train_one(cfg, train_head, norm + "_nocc", sel["kind"], cfg.seed, Xtr, ytr, Xva, yva)\n        res["without_cc(v4 재현)"] = evaluate(NumpyHead.load(info["head_file"], info["spec"]))\n        res["without_cc(v4 재현)"]["val_macro_f1"] = info["best_val_macro_f1"]\n        res["note"] = "악성 종류 라벨이 없어 2종 지표만 계산. JPxxx는 인코더 벤치마크 계열 데이터라 수치가 낙관적일 수 있음."\n        for name in ("with_cc(v5)", "without_cc(v4 재현)"):\n            r = res[name]\n            log(f"holdout [{name}] n={r[\'n\']} (정상 {r[\'n_benign\']}, 악성 {r[\'n_malicious\']}): AUROC {r[\'auroc\']:.4f}, "\n                f"오탐률 {r[\'benign_fpr\']}, 미탐률 {r[\'malicious_fnr\']}, test 확인 {r[\'test_check\']}")\n        mm["jp_holdout"] = res\n        mm["cc_augment"] = P._jload(cfg.path("reports", "p14_cc_augment.json"))\n        return mm\n\n    text = A.run_v3(cfg, P, v2_reports_dir, log, zip_path, extra_rows=extra, post_eval=post)\n    m = P._jload(cfg.path("reports", "metrics.json"))\n    L = ["", "## v5 추가 (개정 6)"]\n    ca = m["cc_augment"]\n    L.append(f"- Common Crawl 정상 보강(train): {ca[\'train\'][\'rows\']}행, 도메인 {ca[\'train\'][\'domains\']}개, "\n             f"홈페이지 형태 {ca[\'train\'][\'homepage_pct\']}%")\n    for name in ("with_cc(v5)", "without_cc(v4 재현)"):\n        r = m["jp_holdout"][name]\n        L.append(f"- JPxxx holdout [{name}] (정상 {r[\'n_benign\']}, 악성 {r[\'n_malicious\']}): AUROC {r[\'auroc\']:.4f}, "\n                 f"오탐률 {r[\'benign_fpr\']}, 미탐률 {r[\'malicious_fnr\']}")\n    text += "\\n".join(L) + "\\n"\n    with open(cfg.path("reports", "run_summary.md"), "w", encoding="utf-8") as f:\n        f.write(text)\n    return text\n'
hits = glob.glob('/kaggle/input/**/qsing_code/qsing_model/__init__.py', recursive=True)
assert hits, 'v2 노트북 출력(qsing_code)을 입력으로 붙여야 합니다'
